SELECT id, session_id, event_type, duration_sec, NTILE(10) OVER w_recent duration_sec_bucket, AVG(duration_sec) OVER (ORDER BY event_time, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) duration_sec_avg_5, PERCENT_RANK() OVER (ORDER BY duration_sec DESC NULLS FIRST) duration_sec_percent_rank, LEAD(duration_sec, 2) OVER (PARTITION BY event_type ORDER BY duration_sec, id) next_duration_sec FROM web_events WINDOW w_recent AS (PARTITION BY event_type, page ORDER BY duration_sec, id);
